def upright_heart_outline(params, swarm_pos, tstart, tend, limits):
    scale, center_z, depth = params
    n = swarm_pos.shape[0]
    targets = np.zeros((n, 3))
    lower = limits["lower"]
    upper = limits["upper"]
    for i in range(n):
        theta = 2.0 * np.pi * i / 10.0
        x = 16.0 * np.sin(theta) * np.sin(theta) * np.sin(theta) * scale
        zshape = (13.0 * np.cos(theta) - 5.0 * np.cos(2.0 * theta) - 2.0 * np.cos(3.0 * theta) - np.cos(4.0 * theta)) * scale
        p = np.array([x, depth, center_z + zshape])
        for j in range(3):
            lo = 100.0 * lower[j]
            hi = 100.0 * upper[j]
            if p[j] < lo:
                p[j] = lo
            if p[j] > hi:
                p[j] = hi
        targets[i] = p
    waypoints = {}
    duration = tend - tstart
    for k in range(1, 13):
        alpha = k / 12.0
        when = tstart + duration * alpha
        pose = swarm_pos + alpha * (targets - swarm_pos)
        waypoints[when] = {}
        for i in range(n):
            waypoints[when][i] = tuple(pose[i])
    return targets, waypoints

