def upright_heart_outline(params, swarm_pos, tstart, tend, limits):
    scale_cm = params[0]
    n = swarm_pos.shape[0]
    final_pos = np.array(swarm_pos, dtype=float, copy=True)
    lo = np.asarray(limits["lower"], dtype=float) * 100.0
    hi = np.asarray(limits["upper"], dtype=float) * 100.0
    targets = np.zeros((n, 3), dtype=float)
    for i in range(n):
        theta = 2.0 * 3.141592653589793 * i / n
        s = np.sin(theta)
        c = np.cos(theta)
        x = scale_cm * s * s * s
        heart_z = 13.0 * c - 5.0 * c * c - 2.0 * c * c * c - c * c * c * c
        z = 100.0 + scale_cm * heart_z / 17.0
        if x < lo[0]:
            x = lo[0]
        if x > hi[0]:
            x = hi[0]
        if 0.0 < lo[1]:
            y = lo[1]
        elif 0.0 > hi[1]:
            y = hi[1]
        else:
            y = 0.0
        if z < lo[2]:
            z = lo[2]
        if z > hi[2]:
            z = hi[2]
        targets[i, 0] = x
        targets[i, 1] = y
        targets[i, 2] = z
        final_pos[i] = targets[i]
    waypoints = {}
    for k in range(1, 9):
        t = tstart + (tend - tstart) * k / 8.0
        frame = {}
        fraction = k / 8.0
        for i in range(n):
            p = swarm_pos[i] * (1.0 - fraction) + targets[i] * fraction
            frame[i] = (float(p[0]), float(p[1]), float(p[2]))
        waypoints[t] = frame
    return final_pos, waypoints

def upright_heart_outline(params, swarm_pos, tstart, tend, limits):
    scale_cm = params[0]
    n = swarm_pos.shape[0]
    final_pos = np.array(swarm_pos, dtype=float, copy=True)
    lo = np.asarray(limits["lower"], dtype=float) * 100.0
    hi = np.asarray(limits["upper"], dtype=float) * 100.0
    targets = np.zeros((n, 3), dtype=float)
    for i in range(n):
        theta = 2.0 * 3.141592653589793 * i / n
        s = np.sin(theta)
        c = np.cos(theta)
        x = scale_cm * s * s * s
        z = 100.0 + scale_cm * (13.0 * c - 5.0 * c * c - 2.0 * c * c * c - c * c * c * c) / 17.0
        y = 0.0
        if x < lo[0]:
            x = lo[0]
        if x > hi[0]:
            x = hi[0]
        if y < lo[1]:
            y = lo[1]
        if y > hi[1]:
            y = hi[1]
        if z < lo[2]:
            z = lo[2]
        if z > hi[2]:
            z = hi[2]
        targets[i] = (x, y, z)
        final_pos[i] = targets[i]
    lanes = np.zeros((n, 3), dtype=float)
    for i in range(n):
        lanes[i, 0] = swarm_pos[i, 0]
        lanes[i, 1] = (i - (n - 1) / 2.0) * 32.0
        lanes[i, 2] = swarm_pos[i, 2]
        if lanes[i, 0] < lo[0]:
            lanes[i, 0] = lo[0]
        if lanes[i, 0] > hi[0]:
            lanes[i, 0] = hi[0]
        if lanes[i, 2] < lo[2]:
            lanes[i, 2] = lo[2]
        if lanes[i, 2] > hi[2]:
            lanes[i, 2] = hi[2]
    waypoints = {}
    steps = 24
    for k in range(1, steps + 1):
        t = tstart + (tend - tstart) * k / steps
        frame = {}
        phase = k / float(steps)
        for i in range(n):
            if phase <= 0.30:
                f = phase / 0.30
                p = swarm_pos[i] * (1.0 - f) + lanes[i] * f
            else:
                q = (phase - 0.30) / 0.70
                start = i / float(n)
                end = (i + 1) / float(n)
                if q <= start:
                    p = lanes[i]
                elif q >= end:
                    p = targets[i]
                else:
                    f = (q - start) / (end - start)
                    p = lanes[i] * (1.0 - f) + targets[i] * f
            frame[i] = (float(p[0]), float(p[1]), float(p[2]))
        waypoints[t] = frame
    return final_pos, waypoints

def upright_heart_outline(params, swarm_pos, tstart, tend, limits):
    size = params[0] / 100.0
    n = swarm_pos.shape[0]
    base = np.array([[0.0,150.0],[-75.0,145.0],[-155.0,115.0],[-170.0,65.0],[-90.0,25.0],[0.0,20.0],[90.0,25.0],[170.0,65.0],[155.0,115.0],[75.0,145.0]], dtype=float)
    lo = np.asarray(limits["lower"], dtype=float) * 100.0
    hi = np.asarray(limits["upper"], dtype=float) * 100.0
    targets = np.zeros((n,3), dtype=float)
    stages = np.zeros((n,3), dtype=float)
    for i in range(n):
        j = i % 10
        x = base[j,0] * size
        z = base[j,1] * size
        if x < lo[0]:
            x = lo[0]
        if x > hi[0]:
            x = hi[0]
        if z < lo[2]:
            z = lo[2]
        if z > hi[2]:
            z = hi[2]
        targets[i] = (x, 0.0, z)
        sy = 60.0 if (i % 2) == 0 else -60.0
        if sy < lo[1]:
            sy = lo[1]
        if sy > hi[1]:
            sy = hi[1]
        stages[i] = (x, sy, z)
    final_pos = np.array(swarm_pos, dtype=float, copy=True)
    for i in range(n):
        final_pos[i] = targets[i]
    waypoints = {}
    steps = 32
    for k in range(1, steps + 1):
        q = k / float(steps)
        t = tstart + (tend - tstart) * q
        frame = {}
        for i in range(n):
            if q < 0.55:
                f = q / 0.55
                p = swarm_pos[i] * (1.0 - f) + stages[i] * f
            else:
                f = (q - 0.55) / 0.45
                p = stages[i] * (1.0 - f) + targets[i] * f
            frame[i] = (float(p[0]), float(p[1]), float(p[2]))
        waypoints[t] = frame
    return final_pos, waypoints

def upright_heart_outline(params, swarm_pos, tstart, tend, limits):
    size = params[0] / 100.0
    n = swarm_pos.shape[0]
    base = np.array([[0.0,150.0],[-75.0,145.0],[-155.0,115.0],[-170.0,65.0],[-90.0,25.0],[0.0,20.0],[90.0,25.0],[170.0,65.0],[155.0,115.0],[75.0,145.0]], dtype=float)
    lo = np.asarray(limits["lower"], dtype=float) * 100.0
    hi = np.asarray(limits["upper"], dtype=float) * 100.0
    targets = np.zeros((n,3), dtype=float)
    stages = np.zeros((n,3), dtype=float)
    for i in range(n):
        j = i % 10
        x = base[j,0] * size
        z = base[j,1] * size
        if x < lo[0]:
            x = lo[0]
        if x > hi[0]:
            x = hi[0]
        if z < lo[2]:
            z = lo[2]
        if z > hi[2]:
            z = hi[2]
        targets[i] = (x, 0.0, z)
        sy = (i - (n - 1) / 2.0) * 38.0
        if sy < lo[1]:
            sy = lo[1]
        if sy > hi[1]:
            sy = hi[1]
        stages[i] = (x, sy, z)
    final_pos = np.array(swarm_pos, dtype=float, copy=True)
    for i in range(n):
        final_pos[i] = targets[i]
    waypoints = {}
    steps = 32
    for k in range(1, steps + 1):
        q = k / float(steps)
        t = tstart + (tend - tstart) * q
        frame = {}
        for i in range(n):
            if q < 0.55:
                f = q / 0.55
                p = swarm_pos[i] * (1.0 - f) + stages[i] * f
            else:
                f = (q - 0.55) / 0.45
                p = stages[i] * (1.0 - f) + targets[i] * f
            frame[i] = (float(p[0]), float(p[1]), float(p[2]))
        waypoints[t] = frame
    return final_pos, waypoints

def upright_heart_outline(params, swarm_pos, tstart, tend, limits):
    scale, center_z, y_depth, depth_spread = params
    n = swarm_pos.shape[0]
    target = np.zeros((n, 3))
    for i in range(n):
        theta = 2.0 * np.pi * i / n
        sx = np.sin(theta)
        cz = np.cos(theta)
        target[i, 0] = 16.0 * sx * sx * sx * scale
        target[i, 1] = y_depth + (depth_spread if i % 2 == 0 else -depth_spread)
        target[i, 2] = (13.0 * cz - 5.0 * np.cos(2.0 * theta) - 2.0 * np.cos(3.0 * theta) - np.cos(4.0 * theta)) * scale + center_z
    lower = np.array(limits["lower"]) * 100.0
    upper = np.array(limits["upper"]) * 100.0
    target = np.maximum(np.minimum(target, upper), lower)
    final_pos = target.copy()
    waypoints = {}
    steps = 40
    for k in range(1, steps + 1):
        a = k / steps
        tm = tstart + (tend - tstart) * a
        pose = swarm_pos.copy()
        if a < 0.25:
            b = a / 0.25
            for i in range(n):
                pose[i, 1] = swarm_pos[i, 1] * (1.0 - b) + target[i, 1] * b
        else:
            q = (a - 0.25) / 0.75
            active = int(q * n)
            if active >= n:
                active = n - 1
            for i in range(n):
                if i < active:
                    b = 1.0
                elif i == active:
                    b = q * n - active
                    if b < 0.0:
                        b = 0.0
                    if b > 1.0:
                        b = 1.0
                else:
                    b = 0.0
                pose[i, 0] = swarm_pos[i, 0] * (1.0 - b) + target[i, 0] * b
                pose[i, 1] = target[i, 1]
                pose[i, 2] = swarm_pos[i, 2] * (1.0 - b) + target[i, 2] * b
        waypoints[tm] = {}
        for i in range(n):
            waypoints[tm][i] = pose[i]
    return final_pos, waypoints

def firework(params, swarm_pos, tstart, tend, limits):
    burst_radius_cm = params[0]
    n = swarm_pos.shape[0]
    duration = tend - tstart
    lower = limits["lower"] * 100.0 + 2.0
    upper = limits["upper"] * 100.0 - 2.0
    hub = np.mean(swarm_pos, axis=0)
    hub = np.clip(hub, lower, upper)

    endpoints = np.zeros((n, 3))
    for i in range(n):
        angle = 2.0 * np.pi * i / n
        direction = np.array([np.cos(angle), np.sin(angle), 0.35 * np.sin(2.0 * angle)])
        raw = hub + burst_radius_cm * direction
        endpoints[i] = np.clip(raw, lower, upper)

    waypoints = {}
    collapse_end = tstart + 0.40 * duration
    for k in range(1, 6):
        fraction = 0.08 * k
        when = tstart + fraction * duration
        alpha = fraction / 0.40
        alpha = min(1.0, alpha)
        pose = swarm_pos * (1.0 - alpha) + hub * alpha
        waypoints[when] = {i: pose[i].copy() for i in range(n)}

    waypoints[collapse_end] = {i: hub.copy() for i in range(n)}
    waypoints[tstart + 0.45 * duration] = {i: hub.copy() for i in range(n)}

    for k in range(1, 10):
        fraction = 0.45 + 0.05 * k
        when = tstart + fraction * duration
        alpha = (fraction - 0.45) / 0.50
        pose = np.zeros((n, 3))
        for i in range(n):
            pose[i] = hub * (1.0 - alpha) + endpoints[i] * alpha
        waypoints[when] = {i: pose[i].copy() for i in range(n)}

    waypoints[tend] = {i: endpoints[i].copy() for i in range(n)}
    final_pos = endpoints.copy()
    return final_pos, waypoints

def firework_collapse_burst(params, swarm_pos, tstart, tend, limits):
    collapse_fraction, burst_radius = params
    n = swarm_pos.shape[0]
    lower = limits["lower"] * 100.0
    upper = limits["upper"] * 100.0
    center = np.mean(swarm_pos, axis=0)
    if center[0] < lower[0]:
        center[0] = lower[0]
    if center[0] > upper[0]:
        center[0] = upper[0]
    if center[1] < lower[1]:
        center[1] = lower[1]
    if center[1] > upper[1]:
        center[1] = upper[1]
    if center[2] < lower[2]:
        center[2] = lower[2]
    if center[2] > upper[2]:
