        frame = {}
        for i in range(n):
            angle = 2.0 * np.pi * float(i) / float(n)
            dx = np.cos(angle)
            dy = np.sin(angle)
            allowed = burst_radius
            if dx > 0.0 and (upper[0] - center[0]) / dx < allowed:
                allowed = (upper[0] - center[0]) / dx
            if dx < 0.0 and (lower[0] - center[0]) / dx < allowed:
                allowed = (lower[0] - center[0]) / dx
            if dy > 0.0 and (upper[1] - center[1]) / dy < allowed:
                allowed = (upper[1] - center[1]) / dy
            if dy < 0.0 and (lower[1] - center[1]) / dy < allowed:
                allowed = (lower[1] - center[1]) / dy
            if allowed < 0.0:
                allowed = 0.0
            r = allowed * u
            p = np.array([center[0] + dx * r, center[1] + dy * r, center[2]])
            frame[i] = p
            if k == burst_steps:
                final_pos[i] = p
        waypoints[tt] = frame
    return final_pos, waypoints

def firework_compact_collapse_burst(params, swarm_pos, tstart, tend, limits):
    collapse_fraction, collapse_radius, burst_radius = params
    n = swarm_pos.shape[0]
    lower = limits["lower"] * 100.0
    upper = limits["upper"] * 100.0
    center = np.mean(swarm_pos, axis=0)
    for j in range(3):
        if center[j] < lower[j]:
