    if burst_radius < collapse_radius + 20.0:
        burst_radius = collapse_radius + 20.0

    total = tend - tstart
    tc = tstart + total * collapse_fraction
    waypoints = {}

    def ray_point(i, radius):
        angle = 2.0 * np.pi * float(i) / float(n)
        dx = np.cos(angle)
        dy = np.sin(angle)
        allowed = burst_radius
        if dx > 0.0 and (upper[0] - center[0]) / dx < allowed:
            allowed = (upper[0] - center[0]) / dx
        if dx < 0.0 and (lower[0] - center[0]) / dx < allowed:
            allowed = (lower[0] - center[0]) / dx
        if dy > 0.0 and (upper[1] - center[1]) / dy < allowed:
            allowed = (upper[1] - center[1]) / dy
        if dy < 0.0 and (lower[1] - center[1]) / dy < allowed:
            allowed = (lower[1] - center[1]) / dy
        if allowed < collapse_radius:
            allowed = collapse_radius
        if radius > allowed:
            radius = allowed
        return np.array([center[0] + dx * radius, center[1] + dy * radius, center[2]])

    compact = {}
    for i in range(n):
        compact[i] = ray_point(i, collapse_radius)
    waypoints[tc] = compact

    final_pos = swarm_pos.copy()
    burst_steps = 20
    for k in range(1, burst_steps + 1):
        u = float(k) / float(burst_steps)
        tt = tc + (tend - tc) * u
