def firework_collapse_burst(params, swarm_pos, tstart, tend, limits):
    collapse_frac, radius_m = params
    duration = tend - tstart
    frac = min(0.8, max(0.1, collapse_frac))
    tc = tstart + frac * duration

    lower = np.asarray(limits["lower"]) * 100.0
    upper = np.asarray(limits["upper"]) * 100.0
    center = np.mean(swarm_pos, axis=0)
    center = np.minimum(upper, np.maximum(lower, center))

    requested = max(0.05, radius_m) * 100.0
    usable = requested
    directions = []
    for i in range(10):
        a = 2.0 * np.pi * i / 10.0
        d = np.asarray([np.cos(a), np.sin(a), 0.0])
        directions.append(d)
        cap = requested
        if d[0] > 0.0:
            cap = min(cap, (upper[0] - center[0]) / d[0])
        elif d[0] < 0.0:
            cap = min(cap, (lower[0] - center[0]) / d[0])
        if d[1] > 0.0:
            cap = min(cap, (upper[1] - center[1]) / d[1])
        elif d[1] < 0.0:
            cap = min(cap, (lower[1] - center[1]) / d[1])
        usable = min(usable, cap)
    usable = max(1.0, 0.9 * usable)

    waypoints = {}
    waypoints[tc] = {}
    for i in range(10):
        waypoints[tc][i] = center.copy()

    for step in range(1, 7):
        t = tc + (tend - tc) * step / 6.0
        fraction = step / 6.0
        waypoints[t] = {}
        for i in range(10):
            waypoints[t][i] = center + fraction * usable * directions[i]

    final_pos = swarm_pos.copy()
    for i in range(10):
        final_pos[i] = center + usable * directions[i]
    return final_pos, waypoints

