        d = directions[i]
        cap = requested
        if d[0] > 0.0:
            cap = min(cap, (upper[0] - center[0] - core_radius) / d[0])
        elif d[0] < 0.0:
            cap = min(cap, (lower[0] - center[0] + core_radius) / d[0])
        if d[1] > 0.0:
            cap = min(cap, (upper[1] - center[1] - core_radius) / d[1])
        elif d[1] < 0.0:
            cap = min(cap, (lower[1] - center[1] + core_radius) / d[1])
