    center[0] = min(upper[0] - core_xy, max(lower[0] + core_xy, center[0]))
    center[1] = min(upper[1] - core_xy, max(lower[1] + core_xy, center[1]))
    center[2] = min(upper[2] - core_z, max(lower[2] + core_z, center[2]))

    requested = max(0.45, radius_m) * 100.0
    directions = []
    for i in range(5):
        angle = 2.0 * np.pi * i / 5.0
        horizontal = np.sqrt(1.0 - 0.3 * 0.3)
        d = np.asarray([horizontal * np.cos(angle), horizontal * np.sin(angle), 0.3])
        directions.append(d)
        directions.append(-d)

    usable = requested
    for d in directions:
        if d[0] > 0.0:
            usable = min(usable, (upper[0] - center[0]) / d[0])
        elif d[0] < 0.0:
            usable = min(usable, (lower[0] - center[0]) / d[0])
        if d[1] > 0.0:
            usable = min(usable, (upper[1] - center[1]) / d[1])
        elif d[1] < 0.0:
            usable = min(usable, (lower[1] - center[1]) / d[1])
        if d[2] > 0.0:
            usable = min(usable, (upper[2] - center[2]) / d[2])
        elif d[2] < 0.0:
            usable = min(usable, (lower[2] - center[2]) / d[2])
    usable = max(35.0, 0.88 * usable)

    core = []
    for i in range(5):
        angle = 2.0 * np.pi * i / 5.0
        p = np.asarray([core_xy * np.cos(angle), core_xy * np.sin(angle), core_z])
        core.append(center + p)
        core.append(center - p)

    waypoints = {}
    waypoints[tc] = {}
    for i in range(10):
        waypoints[tc][i] = core[i].copy()

    for step in range(1, 11):
        t = tc + (tend - tc) * step / 10.0
        f = step / 10.0
        waypoints[t] = {}
        for i in range(10):
            waypoints[t][i] = center + (1.0 - f) * (core[i] - center) + f * usable * directions[i]

