    horizontal = np.sqrt(1.0 - 0.24 * 0.24)
    positive = []
    for i in range(5):
        angle = 2.0 * np.pi * i / 5.0
        positive.append(np.asarray([horizontal * np.cos(angle), horizontal * np.sin(angle), 0.24]))
    directions = []
    for i in range(5):
        directions.append(positive[i])
    for i in range(5):
        directions.append(-positive[i])
    requested = max(0.42, radius_m) * 100.0
    usable = requested
    for d in directions:
        if d[0] > 0.0:
            usable = min(usable, (upper[0] - center[0]) / d[0])
