def sequential_paired_half_orbits(params, swarm_pos, tstart, tend, limits):
    turns, active_fraction = params
    final_pos = swarm_pos.copy()
    waypoints = {}
    n = swarm_pos.shape[0]
    h = n // 2
    duration = tend - tstart
    if h <= 0 or duration <= 0.0:
        return final_pos, waypoints
    if turns < 0.0:
        signed_turns = -turns
    else:
        signed_turns = turns
    if signed_turns < 0.05:
        signed_turns = 0.05
    if active_fraction < 0.1:
        active_fraction = 0.1
    if active_fraction > 1.0:
        active_fraction = 1.0
    slot = duration * active_fraction / float(h)
    segments = int(signed_turns * 48.0)
    if segments < 12:
        segments = 12

    radii = []
    phases = []
    for j in range(h):
        dx = swarm_pos[j + h, 0] - swarm_pos[j, 0]
        dy = swarm_pos[j + h, 1] - swarm_pos[j, 1]
        radii.append(np.sqrt(dx * dx + dy * dy))
        if radii[j] > 0.001:
            phases.append(np.arctan2(dy, dx))
        else:
            phases.append(0.0)

    for j in range(h):
        mover = j + h
        slot_start = tstart + float(j) * slot
        for k in range(1, segments + 1):
            local = float(k) / float(segments)
            tm = slot_start + slot * local
            if tm > tend:
                tm = tend
            angle = phases[j] + 2.0 * np.pi * signed_turns * local
            x = swarm_pos[j, 0] + radii[j] * np.cos(angle)
            y = swarm_pos[j, 1] + radii[j] * np.sin(angle)
            z = swarm_pos[mover, 2]
            waypoints[tm] = {mover: (x, y, z)}
        angle = phases[j] + 2.0 * np.pi * signed_turns
        final_pos[mover, 0] = swarm_pos[j, 0] + radii[j] * np.cos(angle)
        final_pos[mover, 1] = swarm_pos[j, 1] + radii[j] * np.sin(angle)
        final_pos[mover, 2] = swarm_pos[mover, 2]
    return final_pos, waypoints

def orbit_half_around_stationary_half(params, swarm_pos, tstart, tend, limits):
    radius_m, revolutions = params
    final_pos = np.array(swarm_pos, copy=True)
    n = swarm_pos.shape[0]
    if n < 10:
        return final_pos, {}
    lower = np.array(limits["lower"]) * 100.0
    upper = np.array(limits["upper"]) * 100.0
    center = np.mean(swarm_pos[0:5], axis=0)
    radius = radius_m * 100.0
    avail_x = min(center[0] - lower[0], upper[0] - center[0])
    avail_y = min(center[1] - lower[1], upper[1] - center[1])
    avail = min(avail_x, avail_y)
    if avail < 0.0:
        avail = 0.0
    if radius > avail:
        radius = avail
    if radius < 0.0:
        radius = 0.0
    z = center[2]
    if z < lower[2]:
        z = lower[2]
    if z > upper[2]:
        z = upper[2]
    duration = tend - tstart
    if duration <= 0.0:
        return final_pos, {}
    count = int(duration * 6.0 * max(1.0, revolutions)) + 1
    if count < 9:
        count = 9
    waypoints = {}
    for k in range(1, count + 1):
        u = float(k) / float(count)
        tm = tstart + duration * u
        frame = {}
        for j in range(5):
            phase = 2.0 * np.pi * float(j) / 5.0 + 2.0 * np.pi * revolutions * u
            p = (center[0] + radius * np.cos(phase), center[1] + radius * np.sin(phase), z)
            frame[5 + j] = p
            if k == count:
                final_pos[5 + j] = p
        waypoints[tm] = frame
    return final_pos, waypoints

def orbit_half_around_stationary_half_staggered(params, swarm_pos, tstart, tend, limits):
    radius_m, revolutions, z_span_m = params
    final_pos = np.array(swarm_pos, copy=True)
    if swarm_pos.shape[0] < 10:
        return final_pos, {}
    lower = np.array(limits["lower"]) * 100.0
    upper = np.array(limits["upper"]) * 100.0
    center = np.mean(swarm_pos[0:5], axis=0)
    radius = radius_m * 100.0
    xroom = min(center[0] - lower[0], upper[0] - center[0])
    yroom = min(center[1] - lower[1], upper[1] - center[1])
    room = min(xroom, yroom)
    if radius > room - 8.0:
        radius = room - 8.0
    if radius < 15.0:
        radius = 15.0
    span = z_span_m * 100.0
    ztop = upper[2] - 6.0
    zbottom = ztop - span
    if zbottom < lower[2] + 6.0:
        zbottom = lower[2] + 6.0
        ztop = zbottom + span
    if ztop > upper[2] - 2.0:
        ztop = upper[2] - 2.0
    duration = tend - tstart
