def travelling_ripple(params, swarm_pos, tstart, tend, limits):
    amplitude, delay, width = params
    n = swarm_pos.shape[0]
    span = tend - tstart
    if width > span * 0.45:
        width = span * 0.45
    if width < 0.02:
        width = 0.02
    if width + (n - 1) * delay > span * 0.9:
        delay = (span * 0.9 - width) / max(1, n - 1)
    if delay < 0:
        delay = 0

    remaining = list(range(1, n))
    order = [0]
    while len(remaining) > 0:
        best = remaining[0]
        best_d = (swarm_pos[best, 0] - swarm_pos[0, 0]) * (swarm_pos[best, 0] - swarm_pos[0, 0]) + (swarm_pos[best, 1] - swarm_pos[0, 1]) * (swarm_pos[best, 1] - swarm_pos[0, 1])
        for q in remaining:
            d = (swarm_pos[q, 0] - swarm_pos[0, 0]) * (swarm_pos[q, 0] - swarm_pos[0, 0]) + (swarm_pos[q, 1] - swarm_pos[0, 1]) * (swarm_pos[q, 1] - swarm_pos[0, 1])
            if d < best_d:
                best = q
                best_d = d
        order.append(best)
        remaining.remove(best)

    event_times = []
    for rank in range(n):
        start = tstart + rank * delay
        for sample in range(1, 9):
            tm = start + width * sample / 8.0
            if tm > tstart and tm <= tend:
                event_times.append(tm)
    if tend > tstart:
        event_times.append(tend)
    event_times = sorted(event_times)

    low_z = limits["lower"][2] * 100.0
    high_z = limits["upper"][2] * 100.0
    waypoints = {}
    for tm in event_times:
        frame = {}
        for drone in range(n):
            z = swarm_pos[drone, 2]
            for rank in range(n):
                if order[rank] == drone:
                    phase = (tm - tstart - rank * delay) / width
                    if phase > 0.0 and phase < 1.0:
                        z = z + amplitude * 0.5 * (1.0 - np.cos(2.0 * np.pi * phase))
            if z < low_z:
                z = low_z
            if z > high_z:
                z = high_z
            frame[drone] = (swarm_pos[drone, 0], swarm_pos[drone, 1], z)
        waypoints[tm] = frame

    final_pos = swarm_pos.copy()
    for drone in range(n):
        final_pos[drone, 2] = swarm_pos[drone, 2]
    return final_pos, waypoints

