    if n < 1 or span <= 0.0:
        return swarm_pos.copy(), {}

    order = [0]
    remaining = list(range(1, n))
    while len(remaining) > 0:
        best = remaining[0]
        best_d = (swarm_pos[best, 0] - swarm_pos[0, 0]) * (swarm_pos[best, 0] - swarm_pos[0, 0]) + (swarm_pos[best, 1] - swarm_pos[0, 1]) * (swarm_pos[best, 1] - swarm_pos[0, 1])
        for drone in remaining:
            d = (swarm_pos[drone, 0] - swarm_pos[0, 0]) * (swarm_pos[drone, 0] - swarm_pos[0, 0]) + (swarm_pos[drone, 1] - swarm_pos[0, 1]) * (swarm_pos[drone, 1] - swarm_pos[0, 1])
            if d < best_d:
                best = drone
                best_d = d
        order.append(best)
        remaining.remove(best)

    slot = span / (n + 1.0)
    pulse = pulse_width
    if pulse > slot * 0.55:
        pulse = slot * 0.55
    if pulse < 0.04:
        pulse = 0.04
    if pulse > span * 0.45:
        pulse = span * 0.45

    low_z = limits["lower"][2] * 100.0
    high_z = limits["upper"][2] * 100.0
    waypoints = {}
    sample_count = 6
    for rank in range(n):
        drone = order[rank]
        start = tstart + (rank + 0.5) * slot
        for sample in range(1, sample_count + 1):
            tm = start + pulse * sample / sample_count
            if tm <= tstart or tm > tend:
                continue
            phase = sample / float(sample_count)
            lift = amplitude * 0.5 * (1.0 - np.cos(2.0 * np.pi * phase))
            z = swarm_pos[drone, 2] + lift
            if z < low_z:
                z = low_z
            if z > high_z:
                z = high_z
            frame = {}
            for k in range(n):
                if k == drone:
                    frame[k] = (swarm_pos[k, 0], swarm_pos[k, 1], z)
                else:
