def travelling_ripple(params, swarm_pos, tstart, tend, limits):
    source, amplitude_cm, duration_s = params
    n = swarm_pos.shape[0]
    base = swarm_pos.copy()
    if n == 0:
        return base, {}
    src = max(0, min(int(source), n - 1))
    lower = limits["lower"] * 100.0
    upper = limits["upper"] * 100.0
    dx = swarm_pos[:, 0] - swarm_pos[src, 0]
    dy = swarm_pos[:, 1] - swarm_pos[src, 1]
    order = np.argsort(dx * dx + dy * dy)
    available = np.min(upper[2] - base[:, 2])
    amp = min(abs(float(amplitude_cm)), max(0.0, 0.75 * available))
    span = min(max(float(duration_s), 0.1), max(0.0, tend - tstart))
    if span <= 0.0:
        return base, {}
    width = span / (2.5 * float(n))
    delay_step = 2.0 * width
    waypoints = {}
    samples = 96
    for s in range(1, samples + 1):
        now = tstart + span * float(s) / float(samples)
        elapsed = now - tstart
        point = base.copy()
        for rank in range(n):
            drone = int(order[rank])
            phase = (elapsed - delay_step * float(rank)) / width
            if phase > 0.0 and phase < 1.0:
                point[drone, 2] = base[drone, 2] + amp * np.sin(np.pi * phase)
            else:
                point[drone, 2] = base[drone, 2]
            point[drone, 2] = min(upper[2], max(lower[2], point[drone, 2]))
        waypoints[now] = {i: tuple(point[i]) for i in range(n)}
    return base, waypoints

