def travelling_radial_ripple(params, swarm_pos, tstart, tend, limits):
    source, speed, amplitude = params
    n = len(swarm_pos)
    src = source
    if src < 0:
        src = 0
    if src >= n:
        src = n - 1
    duration = tend - tstart
    cx = swarm_pos[src, 0]
    cy = swarm_pos[src, 1]
    radii = []
    max_radius = 0.0
    for i in range(n):
        dx = swarm_pos[i, 0] - cx
        dy = swarm_pos[i, 1] - cy
        r = np.sqrt(dx * dx + dy * dy)
        radii.append(r)
        if r > max_radius:
            max_radius = r
    width = 0.12 * max_radius
    if width < 15.0:
        width = 15.0
    lower_z = limits["lower"][2] * 100.0
    upper_z = limits["upper"][2] * 100.0
