    steps = 12 + int(8.0 * duration)
    if steps < 16:
        steps = 16
    if steps > 96:
        steps = 96
    for k in range(1, steps + 1):
        u = float(k) / float(steps)
        tt = tstart + duration * u
        front = max_radius * speed * u
        for i in range(n):
            distance_from_front = (radii[i] - front) / width
            lift = amplitude * np.exp(-0.5 * distance_from_front * distance_from_front)
            z = swarm_pos[i, 2] + lift
            if z < lower_z:
                z = lower_z
            if z > upper_z:
                z = upper_z
            final_pos[i, 2] = z
        frame = {}
        for i in range(n):
            frame[i] = (float(final_pos[i, 0]), float(final_pos[i, 1]), float(final_pos[i, 2]))
        waypoints[tt] = frame
