            if abs(pos[drone, step, 0] - reference_x) > 55.0:
                planar = False
    for drone in range(10):
        column = drone % 5
        row = drone // 5
        for step in range(begin, len(time)):
            if abs(pos[drone, step, 1] - ys[column]) > 48.0:
                lattice = False
            if abs(pos[drone, step, 2] - zs[row]) > 48.0:
                lattice = False
    if len(time) > begin:
        first = 0.0
        last = 0.0
        for drone in range(10):
            first = first + pos[drone, begin, 0]
            last = last + pos[drone, len(time) - 1, 0]
        first = first / 10.0
        last = last / 10.0
        if abs(last - first) < 100.0:
            moving = False
        if x_end >= x_start and last <= first:
            moving = False
        if x_end < x_start and last >= first:
            moving = False
